const app = express();
const uploadRoot=path.resolve('storage/uploads');
await fs.mkdir(uploadRoot,{recursive:true});
const acceptedMimeTypes=new Set(['image/jpeg','image/png','image/webp','application/pdf']);
const upload=multer({
  storage:multer.diskStorage({destination:uploadRoot,filename:(_request,file,callback)=>callback(null,`${crypto.randomUUID()}${path.extname(file.originalname).toLowerCase().slice(0,10)}`)}),
  limits:{fileSize:8*1024*1024,files:5},
  fileFilter:(_request,file,callback)=>callback(null,acceptedMimeTypes.has(file.mimetype)),
});
app.disable('x-powered-by');
app.use(helmet());
app.use(cors({ origin:(origin,callback)=>callback(null,!origin||origin===config.frontendUrl), credentials: true }));
app.use(express.json({ limit: '1mb' }));
app.use((error:unknown,_request:express.Request,response:express.Response,next:express.NextFunction)=>{if(error instanceof SyntaxError&&'body' in error)return response.status(400).json({error:'Malformed JSON request.'});next(error);});
app.use((request,response,next)=>{const requestId=crypto.randomUUID();response.setHeader('X-Request-Id',requestId);const started=Date.now();response.on('finish',()=>{void pool.query('INSERT INTO structured_logs(log_level,log_type,message,context_json,request_id) VALUES(?,?,?,?,?)',[response.statusCode>=500?'error':response.statusCode>=400?'warn':'info','application',`${request.method} ${request.path}`,JSON.stringify({status:response.statusCode,durationMs:Date.now()-started,ip:request.ip}),requestId]).catch(()=>undefined);});next();});
app.use('/api/auth', rateLimit({ windowMs: 15 * 60_000, limit: 50, standardHeaders: 'draft-8', legacyHeaders: false }));

const roleToClient = (role: string) => ({ CITIZEN:'citizen', STAFF:'staff', SUPERVISOR:'supervisor', ADMINISTRATOR:'admin', NATIONAL_ADMIN:'super-admin' }[role] || 'citizen');
const publicUser = (user: AuthUser) => ({ id:user.id,fullName:user.fullName,email:user.email,phone:user.phone,role:roleToClient(user.role),roleLabel:user.role.split('_').map(part=>part[0]+part.slice(1).toLowerCase()).join(' '),municipality:user.municipality||null,municipalityId:user.municipalityId||null,district:user.district||null,profileImageUrl:user.profileUploadId?`/api/uploads/${user.profileUploadId}`:null });
const audit = async (userId: number | null, action: string, request: express.Request, entityType?: string, entityId?: number, metadata?: unknown) => {
  await pool.query('INSERT INTO audit_logs (user_id,action,entity_type,entity_id,ip_address,metadata_json) VALUES (?,?,?,?,?,?)',
    [userId, action, entityType || null, entityId || null, request.ip, metadata ? JSON.stringify(metadata) : null]);
};
const csvCell=(value:unknown)=>`"${String(value??'').replace(/"/g,'""')}"`;
const pdfEscape=(value:string)=>value.replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)').replace(/[^\x20-\x7E]/g,'?');
const createTextPdf=(title:string,lines:string[])=>{
  const pages:Array<string[]>=[];for(let index=0;index<lines.length;index+=42)pages.push(lines.slice(index,index+42));if(!pages.length)pages.push(['No records found.']);
  const objects:string[]=[];const add=(body:string)=>{objects.push(body);return objects.length;};
  const catalog=add('');const pagesId=add('');const font=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');const pageIds:number[]=[];
  for(const [pageIndex,pageLines] of pages.entries()){const commands=[`BT /F1 14 Tf 50 790 Td (${pdfEscape(title)}) Tj`,`0 -22 Td /F1 8 Tf (${pdfEscape(`Page ${pageIndex+1} of ${pages.length}`)}) Tj`,...pageLines.map(line=>`0 -16 Td (${pdfEscape(line.slice(0,125))}) Tj`),'ET'].join('\n');const content=add(`<< /Length ${Buffer.byteLength(commands)} >>\nstream\n${commands}\nendstream`);pageIds.push(add(`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${font} 0 R >> >> /Contents ${content} 0 R >>`));}
  objects[catalog-1]=`<< /Type /Catalog /Pages ${pagesId} 0 R >>`;objects[pagesId-1]=`<< /Type /Pages /Kids [${pageIds.map(id=>`${id} 0 R`).join(' ')}] /Count ${pageIds.length} >>`;
  let output='%PDF-1.4\n';const offsets=[0];objects.forEach((body,index)=>{offsets.push(Buffer.byteLength(output));output+=`${index+1} 0 obj\n${body}\nendobj\n`;});const xref=Buffer.byteLength(output);output+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.slice(1).map(offset=>String(offset).padStart(10,'0')+' 00000 n ').join('\n')}\ntrailer\n<< /Size ${objects.length+1} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF`;return Buffer.from(output);
};

app.get('/api/health', async (_request, response) => {
  try { await checkDatabase(); response.json({ status:'ok', database:'connected', environment:config.env }); }
  catch { response.status(503).json({ status:'degraded', database:'unavailable' }); }
});

app.post('/api/auth/register', async (request, response) => {
  const parsed = z.object({ fullName:z.string().min(3).max(160), email:z.string().email(), phone:z.string().min(7).max(40), password:z.string().min(10).max(128) }).safeParse(request.body);
  if (!parsed.success) return response.status(422).json({ error:'Invalid registration details.', fields:parsed.error.flatten().fieldErrors });
  try {
    const hash = await bcrypt.hash(parsed.data.password, 12);
    const [result] = await pool.query<any>(`INSERT INTO users (full_name,email,phone,password_hash,role_id,status)
      SELECT ?,LOWER(?),?,?,id,'active' FROM roles WHERE code='CITIZEN'`, [parsed.data.fullName,parsed.data.email,parsed.data.phone,hash]);
    await pool.query('INSERT IGNORE INTO user_profiles(user_id) VALUES(?)',[result.insertId]);await pool.query('INSERT IGNORE INTO user_preferences(user_id) VALUES(?)',[result.insertId]);
    const [rows] = await pool.query<any[]>('SELECT u.id,u.full_name AS fullName,u.email,u.phone,r.code AS role,u.municipality_id municipalityId,m.name municipality,d.name district,p.profile_upload_id profileUploadId FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN municipalities m ON m.id=u.municipality_id LEFT JOIN districts d ON d.id=u.district_id LEFT JOIN user_profiles p ON p.user_id=u.id WHERE u.id=?', [result.insertId]);
    await pool.query("INSERT INTO notifications(user_id,type,title,body) VALUES(?,'welcome','Welcome to ECOCLEAN SL','Your citizen account is ready. You can now submit and track waste reports.')",[rows[0].id]);await issueSession(request, response, rows[0]); await audit(rows[0].id,'auth.register',request,'user',rows[0].id); response.status(201).json({ user:publicUser(rows[0]) });
  } catch (error:any) { response.status(error?.code === 'ER_DUP_ENTRY' ? 409 : 500).json({ error:error?.code === 'ER_DUP_ENTRY' ? 'Email or phone already registered.' : 'Registration failed.' }); }
});

app.post('/api/auth/login', async (request, response) => {
  const parsed = z.object({ identifier:z.string().min(3).max(190).optional(),email:z.string().min(3).max(190).optional(),password:z.string().min(1),remember:z.boolean().optional() }).refine(data=>Boolean(data.identifier||data.email)).safeParse(request.body);
  if (!parsed.success) return response.status(422).json({ error:'Email or phone number and password are required.' });const identifier=(parsed.data.identifier||parsed.data.email||'').trim();
  const [rows] = await pool.query<any[]>(`SELECT u.id,u.full_name AS fullName,u.email,u.phone,u.password_hash,u.failed_login_count,u.locked_until,r.code AS role,u.municipality_id municipalityId,m.name municipality,d.name district,p.profile_upload_id profileUploadId
    FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN municipalities m ON m.id=u.municipality_id LEFT JOIN districts d ON d.id=u.district_id LEFT JOIN user_profiles p ON p.user_id=u.id WHERE (u.email=LOWER(?) OR u.phone=?) AND u.status='active' AND u.deleted_at IS NULL LIMIT 1`, [identifier,identifier]);
  if(rows[0]?.locked_until&&new Date(rows[0].locked_until)>new Date())return response.status(423).json({error:'Account temporarily locked after repeated failed sign-in attempts.'});
  const valid=rows[0]&&await bcrypt.compare(parsed.data.password,rows[0].password_hash);await pool.query('INSERT INTO login_attempts(email,user_id,ip_address,device_hash,successful,failure_reason) VALUES(?,?,?,?,?,?)',[identifier,rows[0]?.id||null,request.ip,requestDeviceHash(request),Boolean(valid),valid?null:'invalid_credentials']);
  if(!valid){if(rows[0]){const failures=Number(rows[0].failed_login_count||0)+1;await pool.query('UPDATE users SET failed_login_count=?,locked_until=IF(? >= 5,DATE_ADD(NOW(),INTERVAL 30 MINUTE),locked_until) WHERE id=?',[failures,failures,rows[0].id]);if(failures>=5)await pool.query("INSERT INTO security_events(user_id,event_type,severity,ip_address,device_hash,details_json) VALUES(?,'account_lockout','high',?,?,?)",[rows[0].id,request.ip,requestDeviceHash(request),JSON.stringify({failures})]);}await audit(rows[0]?.id||null,'auth.login_failed',request);return response.status(401).json({error:'Invalid email or password.'});}
  await pool.query('UPDATE users SET last_login_at=NOW(),failed_login_count=0,locked_until=NULL WHERE id=?',[rows[0].id]);await issueSession(request,response,rows[0],parsed.data.remember);await audit(rows[0].id,'auth.login',request);response.json({user:publicUser(rows[0])});
});
