app.patch('/api/auth/profile',authenticate,async(request,response)=>{const parsed=z.object({fullName:z.string().min(3).max(160),email:z.string().email(),phone:z.string().min(7).max(40).nullable().optional()}).safeParse(request.body);if(!parsed.success)return response.status(422).json({error:'Invalid profile details.',fields:parsed.error.flatten().fieldErrors});await pool.query('UPDATE users SET full_name=?,email=LOWER(?),phone=? WHERE id=?',[parsed.data.fullName,parsed.data.email,parsed.data.phone||null,request.authUser!.id]);await audit(request.authUser!.id,'profile.updated',request,'user',request.authUser!.id);const [rows]=await pool.query<any[]>(`SELECT u.id,u.full_name AS fullName,u.email,u.phone,r.code role,u.municipality_id municipalityId,m.name municipality,d.name district,p.profile_upload_id profileUploadId FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN municipalities m ON m.id=u.municipality_id LEFT JOIN districts d ON d.id=u.district_id LEFT JOIN user_profiles p ON p.user_id=u.id WHERE u.id=?`,[request.authUser!.id]);response.json({user:publicUser(rows[0])});});
app.post('/api/auth/logout', authenticate, async (request,response) => {const token=request.headers.cookie?.match(/ecoclean_session=([^;]+)/)?.[1];if(token){const payload=jwt.verify(decodeURIComponent(token),config.jwtSecret) as jwt.JwtPayload;if(payload.sid)await pool.query('UPDATE user_sessions SET revoked_at=NOW(),revoked_by=? WHERE id=?',[request.authUser!.id,payload.sid]);}await audit(request.authUser!.id,'auth.logout',request);clearSession(response);response.status(204).end();});
app.post('/api/auth/forgot-password', async (request,response) => {
  const email = z.string().email().safeParse(request.body?.email); if (!email.success) return response.status(422).json({ error:'Valid email required.' });
  const [rows] = await pool.query<any[]>('SELECT id FROM users WHERE email=LOWER(?) AND status=\'active\' LIMIT 1',[email.data]);
  let developmentToken: string|undefined;
  if (rows[0]) { const token=crypto.randomBytes(24).toString('hex'); developmentToken=config.env==='production'?undefined:token; await pool.query('INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,SHA2(?,256),DATE_ADD(NOW(),INTERVAL 30 MINUTE))',[rows[0].id,token]); }
  response.json({ message:'If the account exists, recovery instructions have been generated.', developmentToken });
});
app.post('/api/auth/reset-password', async (request,response) => {
  const parsed=z.object({token:z.string().min(20),password:z.string().min(10).max(128)}).safeParse(request.body); if(!parsed.success)return response.status(422).json({error:'Valid token and password required.'});
  const [rows]=await pool.query<any[]>(`SELECT id,user_id FROM password_reset_tokens WHERE token_hash=SHA2(?,256) AND used_at IS NULL AND expires_at>NOW() LIMIT 1`,[parsed.data.token]);
  if(!rows[0])return response.status(422).json({error:'Recovery token is invalid or expired.'});
  const hash=await bcrypt.hash(parsed.data.password,12); await pool.query('UPDATE users SET password_hash=? WHERE id=?',[hash,rows[0].user_id]); await pool.query('UPDATE password_reset_tokens SET used_at=NOW() WHERE id=?',[rows[0].id]); response.json({message:'Password updated.'});
});

