  const [rows]=await pool.query<any[]>('SELECT id,label,key_prefix AS keyPrefix,last_four AS lastFour,created_at AS createdAt,expires_at AS expiresAt FROM api_keys WHERE owner_user_id=? AND revoked_at IS NULL AND (expires_at IS NULL OR expires_at>NOW()) ORDER BY created_at DESC LIMIT 1',[request.authUser!.id]);
  response.json({data:rows[0] ? {...rows[0],maskedKey:`${rows[0].keyPrefix}••••••••${rows[0].lastFour}`} : null});
