app.post('/api/support/tickets',authenticate,async(request,response)=>{const parsed=z.object({subject:z.string().min(3),category:z.string().min(2).default('general'),priority:z.enum(['low','medium','high','critical']).default('medium'),message:z.string().min(2)}).safeParse(request.body);if(!parsed.success)return response.status(422).json({error:'Invalid support request.'});const reference=`SUP-${new Date().getFullYear()}-${crypto.randomInt(100000,999999)}`;const connection=await pool.getConnection();try{await connection.beginTransaction();const [ticket]=await connection.query<any>('INSERT INTO support_tickets(reference,opened_by,subject,category,priority) VALUES(?,?,?,?,?)',[reference,request.authUser!.id,parsed.data.subject,parsed.data.category,parsed.data.priority]);const [conversation]=await connection.query<any>('INSERT INTO conversations(ticket_id,subject,created_by) VALUES(?,?,?)',[ticket.insertId,parsed.data.subject,request.authUser!.id]);await connection.query('INSERT INTO conversation_participants(conversation_id,user_id) VALUES(?,?)',[conversation.insertId,request.authUser!.id]);await connection.query('INSERT INTO messages(conversation_id,sender_user_id,body) VALUES(?,?,?)',[conversation.insertId,request.authUser!.id,parsed.data.message]);await connection.commit();await audit(request.authUser!.id,'ticket.created',request,'support_ticket',ticket.insertId);response.status(201).json({data:{id:ticket.insertId,reference,conversationId:conversation.insertId,...parsed.data,status:'open'}});}catch(error){await connection.rollback();throw error;}finally{connection.release();}});
